import React, { useState } from "react";
import axios from "axios";
import "./LoginPage.css"; // optional styling file

function LoginPage({ onLogin }) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const handleLogin = async () => {
    try {
      const res = await axios.post("http://localhost:5000/api/users/login", {
        email,
        password,
      });
      // Save JWT token
      localStorage.setItem("token", res.data.token);
      onLogin(); // redirect to Dashboard
    } catch (err) {
      alert("Login failed: " + (err.response?.data?.message || err.message));
    }
  };

  const handleRegister = async () => {
    try {
      const res = await axios.post("http://localhost:5000/api/users/register", {
        name: email.split("@")[0], // simple default name
        email,
        password,
      });
      localStorage.setItem("token", res.data.token);
      onLogin();
    } catch (err) {
      alert("Register failed: " + (err.response?.data?.message || err.message));
    }
  };

  return (
    <div className="login-container">
      <h2>Nityo Login</h2>

      {/* Instructions Section */}
      <div className="instructions">
        <h4>📋 Instructions</h4>
        <ul>
          <li>Add tasks with name, description, and time.</li>
          <li>Track workflow (Pending / In‑Progress / Completed).</li>
          <li>Manage events with date and time.</li>
          <li>Get reminders and notifications before deadlines.</li>
          <li>View productivity reports with progress bar.</li>
          <li>Logout anytime from Dashboard top bar.</li>
        </ul>
      </div>

      {/* Login Form */}
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
      />

      <div className="login-actions">
        <button onClick={handleLogin}>Login</button>
        <button onClick={handleRegister}>Register</button>
      </div>
    </div>
  );
}

export default LoginPage;
